exports.code = async (inputs) => {
  const incidents = inputs.open_incidents || [];
  const now = Date.now();
  const atRisk = [];
  for (const inc of incidents) {
    const ageMinutes = (now - new Date(inc.created_at).getTime()) / 60000;
    if (inc.severity === 'CRITICAL' && ageMinutes > 15) {
      atRisk.push({ ...inc, ageMinutes: Math.round(ageMinutes), slaLimit: 15 });
    } else if (inc.severity === 'HIGH' && ageMinutes > 60) {
      atRisk.push({ ...inc, ageMinutes: Math.round(ageMinutes), slaLimit: 60 });
    }
  }
  return { breaches: atRisk };
};
